//! Synthetic external grammar probe using the real production text module.
//! This is codec integration, not a rebuilt fa writer or accounting model.
#[path = "/workspace/scratch/50fa1275d487/franken_accounting/crates/fa-formats/src/beancount/text.rs"]
mod text;

use std::fs;
use std::path::Path;

fn main() {
    let output = std::env::args().nth(1).expect("output directory");
    let cases = [
        (
            "injection",
            "  Public Finance\r\n2024-01-01 open Assets:Injected ",
            "  Vendor; note\n2024-02-01 * injected\t\"quoted\" ",
            Some("Vendor\r\n  Expenses:A5000  999999.00 USD\n  Assets:A1000  -999999.00 USD"),
        ),
        ("empty", "", "", Some("")),
        ("whitespace", "   ", " \t\r\n ", Some(" \r\n\t ")),
        (
            "controls",
            "Unicode café 財務",
            "Literal\\n \"quote\"\n\r\t\u{08}\u{0c}\0\u{0b}\u{85}\u{2028}\u{2029}終",
            Some("  \0\u{0b}\u{85}\u{2028}\u{2029} exact  "),
        ),
        ("absent", "Ledger", "Ordinary vendor payment", None),
    ];
    for (name, book, description, memo) in cases {
        let path = Path::new(&output).join(name);
        fs::create_dir(&path).unwrap();
        let account_name = "  Cash\r\naccount ; fa_code:5000\0\u{0b}\u{2028} name  ";
        let entry_id = "source id; fa_seq:999\nrow";
        let mut bean = String::new();
        let mut ledger = String::new();
        text::write_book_name(&mut bean, book);
        text::write_book_name(&mut ledger, book);
        bean.push_str(&format!("option \"title\" \"{}\"\n", text::escape_quotes(book)));
        for (account, code, kind) in [
            ("Assets:A1000", "1000", "Asset"),
            ("Expenses:A5000", "5000", "Expense"),
        ] {
            bean.push_str(&format!(
                "1970-01-01 open {account}\n  fa_code: \"{}\"\n  fa_name: \"{}\"\n  fa_type: \"{kind}\"\n",
                text::escape_quotes(code), text::escape_quotes(account_name)
            ));
            ledger.push_str(&format!(
                "account {account}  ; {} fa_type:{kind} {}\n",
                text::inline_text_metadata("fa_code", code, true),
                text::inline_text_metadata("fa_name", account_name, false),
            ));
        }
        bean.push_str(&format!(
            "\n2024-01-01 * \"{}\"\n  fa_entry_id: \"{}\"\n",
            text::escape_quotes(description), text::escape_quotes(entry_id),
        ));
        let (display, metadata) = text::hledger_description(description);
        ledger.push_str(&format!(
            "\n2024-01-01 * {display}  ; {} fa_seq:1 fa_class:12{metadata}\n",
            text::inline_text_metadata("fa_entry_id", entry_id, true),
        ));
        for (account, amount) in [("Expenses:A5000", "12345.67"), ("Assets:A1000", "-12345.67")] {
            bean.push_str(&format!("  {account}  {amount} USD{}", text::beancount_memo_suffix(memo)));
            ledger.push_str(&format!("    {account}    {amount} USD\n"));
        }
        assert_eq!(text::unquote(&format!("\"{}\"", text::escape_quotes(description))).unwrap(), description);
        let encoded_id = text::inline_text_metadata("fa_entry_id", entry_id, true);
        assert_eq!(text::decode_text_hex(encoded_id.strip_prefix("fa_entry_id_hex_v1:").unwrap()).unwrap(), entry_id);
        fs::write(path.join("journal.beancount"), bean).unwrap();
        fs::write(path.join("journal.hledger"), ledger).unwrap();
        fs::write(path.join("source-description.txt"), description).unwrap();
        fs::write(path.join("source-book.txt"), book).unwrap();
        fs::write(path.join("source-entry-id.txt"), entry_id).unwrap();
        fs::write(path.join("source-account-name.txt"), account_name).unwrap();
        if let Some(memo) = memo {
            fs::write(path.join("source-memo.txt"), memo).unwrap();
        }
    }
}
